INSERT INTO `courses` VALUES (3151026,'전공기초수학 (Introduction to Mathematics for Engineering)','일변수함수의 극한, 미분, 적분을 학습하며, 이를 공학적 문제 해결에 적용하는 방법을 학습',2,1,0),(3151027,'AI융합기초수학 (Introduction to Mathematics for AI Convergence)','공학-AI 융합에 필수적인 선형대수와 다변수 미적분 개념을 학습해 문제 해결 역량을 기름',2,2,0),(3151028,'객체지향프로그래밍1 (Object Oriented Programming 1)','객체지향프로그래밍 개념을 이해하고, 자바 문법부터 GUI, 스윙, 네트워크, DB까지 다양한 자바 응용기술을 학습',3,3,0),(3151029,'안드로이드프로그래밍 (Android Programming)','자바 기반 안드로이드 프로그래밍으로 앱 개발에 필요한 UI, 데이터 처리, 멀티미디어, 구글 지도 등을 학습',3,6,0),(3151030,'운영체제와컴퓨터설계 (Operating System and Computer Design)','운영체제의 구조와 프로세스·기억장치·입출력·파일 관리 기법 및 스케줄링 알고리즘을 학습',3,6,0),(3151031,'보안코딩실습 (Secure Coding Practices )','소프트웨어 보안 취약점과 방어적 프로그래밍, 보안 설계 및 공격 대응 기법을 실습 중심으로 학습',3,4,0),(3151032,'AI와재난현장 (AI in Disaster Management Field)','재난 대응에 활용되는 AI·ICT 기술을 학습하고 적용 사례를 조사하여 재난관리 이해와 대응 역량을 향상함',3,4,0),(3151033,'무선네트워크와응용 (Wireless Networks and Applications )','무선 네트워크의 기본 개념과 프로토콜, 다양한 무선 기술 및 응용, 주파수 사용과 공공 정책 이슈를 학습',3,5,0),(3151034,'기상기후빅데이터 (Big Data in Weather and Climate)','빅데이터 개념을 바탕으로 기상기후 빅데이터의 수집, 분석, 시각화 이론과 기술을 학습',3,5,0),(3151035,'AI와재난모델링 (AI in Disaster Modeling)','과거 재난 빅데이터를 분석·학습하여 자연재난 예측 모델을 개발하고, 실습을 통해 AI 기반 재난관리 역량과 실무 기초 지식을 학습',3,5,0),(3151036,'지능형센서및센서네트워크 (Intelligent Sensors and Sensor Networks )','무선 센서 네트워크의 이론, 설계, 응용을 학습하고 데이터 융합, 보안, 자원 관리 등 실제 과제를 실습 중심으로 익힘',3,6,0),(3151037,'컴퓨터시스템 (Computer System)','컴퓨터 구조 전반과 특수 컴퓨터·입출력 설계에 대한 지식을 학습하고 설계 능력을 익힘',3,6,0),(3151038,'신호해석및처리 (Signal Analysis and Processing)','신호해석 이론을 바탕으로 디지털 필터 등 신호처리 시스템 설계에 적용하는 문제를 학습',3,8,0),(3151039,'전자기학1 (Electromagnetics 1)','전기와 자기 현상의 기본 원리와 관련 수학 지식, 소자 원리, 실생활 활용을 학습',3,3,0),(3151040,'전자기학2 (Electromagnetics 2)','맥스웰 방정식을 바탕으로 전자기장의 발생과 전파 특성, 무선 환경에서의 신호 전달 원리를 학습',2,4,0),(3151041,'기초회로실험 (Basic Circuit Experiment)','기본 소자로 회로를 구성·측정하며 동작 특성과 실험 장비의 사용 및 측정법을 학습',2,4,0),(3151042,'전자AI시스템공학개론 (Introduction of Electronic and AI system Engineering)','전자AI시스템공학과 관련된 다양한 분야에 대한 역가, 현재의 기술동향 미래의 트랜드